const raw = $input.first().json;
const auditState = JSON.parse(raw.audit_state);
const body = ($('POST /audit/session/segment').item.json.body) || {};
const rfpText = body.rfp_text || '';
const draftText = body.draft_text || '';

function stripMd(s) {
  return s
    .replace(/^\s*#{1,6}\s+/, '')
    .replace(/^\s*[-*]\s+/, '')
    .replace(/^\s*\d+[.)]\s+/, '')
    .replace(/\*\*/g, '')
    .replace(/\*/g, '')
    .trim();
}
function isHeading(line) { return /^\s*#{1,6}\s+/.test(line); }
function isListItem(line) { return /^\s*([-*]\s+|\d+[.)]\s+)/.test(line); }

function segmentDocument(rawText, docType) {
  const segments = [];
  if (!rawText) return segments;
  const lines = rawText.split('\n');
  const lineStart = [];
  let posn = 0;
  for (let i = 0; i < lines.length; i++) { lineStart.push(posn); posn += lines[i].length + 1; }
  let currentSection = 'preamble';
  let paraIdx = 0;
  let para = null;

  function pushSeg(start, end, textVal) {
    if (!textVal.length) return;
    segments.push({
      id: docType + '_' + String(paraIdx + 1).padStart(3, '0'),
      section: currentSection,
      para_idx: paraIdx,
      char_span: [start, end],
      text: textVal,
    });
    paraIdx++;
  }
  function flushPara() {
    if (!para) return;
    const start = lineStart[para.startLine];
    const end = lineStart[para.endLine] + lines[para.endLine].length;
    const rawBlock = rawText.slice(start, end);
    const textVal = rawBlock.split('\n').map(function (l) { return stripMd(l); }).filter(function (l) { return l.length; }).join(' ');
    pushSeg(start, end, textVal);
    para = null;
  }
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim() === '') { flushPara(); continue; }
    if (isHeading(line)) { flushPara(); currentSection = stripMd(line); continue; }
    if (isListItem(line)) { flushPara(); para = { startLine: i, endLine: i }; continue; }
    if (para) { para.endLine = i; } else { para = { startLine: i, endLine: i }; }
  }
  flushPara();
  return segments;
}

const rfpSegments = segmentDocument(rfpText, 'rfp');
const draftSegments = segmentDocument(draftText, 'draft');
auditState.rfp_segments = rfpSegments;
auditState.draft_segments = draftSegments;
return [{ json: { session_id: raw.session_id, audit_state: JSON.stringify(auditState), rfp_segments: rfpSegments, draft_segments: draftSegments } }];

const raw = $input.first().json;
const auditState = JSON.parse(raw.audit_state);
const segs = auditState.rfp_segments || [];
if (!segs.length) {
  return [{ json: { has_segments: false, session_id: raw.session_id } }];
}
let segText = '';
for (let i = 0; i < segs.length; i++) { segText += segs[i].id + ': ' + segs[i].text + '\n'; }
const validIds = segs.map(function (s) { return s.id; });
const prompt = [
  'You are a senior proposal requirements analyst.',
  'Below is a list of RFP segments, each line formatted as "<segment_id>: <segment_text>".',
  'Extract every DISTINCT requirement as one object.',
  'Rules:',
  '- category MUST be exactly one of: Technical, Functional, Budget, Timeline, Compliance/SLA, Risk/Assumptions. Pick the closest.',
  '- criticality = "hard" if the RFP uses mandatory language (must, required, shall, mandatory, no migration, etc.), otherwise "soft".',
  '- source_segment_ids MUST only reference segment ids that appear in the list below. Never invent an id.',
  '- Also capture any budget statement and any timeline statement as their own requirement items.',
  '',
  'RFP SEGMENTS:',
  segText,
].join('\n');
const responseSchema = {
  type: 'OBJECT',
  properties: {
    requirements: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          requirement_text: { type: 'STRING' },
          category: { type: 'STRING' },
          criticality: { type: 'STRING' },
          source_segment_ids: { type: 'ARRAY', items: { type: 'STRING' } },
        },
        required: ['requirement_text', 'category', 'criticality', 'source_segment_ids'],
      },
    },
  },
  required: ['requirements'],
};
const requestBody = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: 'application/json', responseSchema: responseSchema },
};
return [{ json: { has_segments: true, session_id: raw.session_id, audit_state: raw.audit_state, valid_ids: validIds, request_body: requestBody } }];

const httpResp = $input.first().json;
const prep = $('Prepare extraction').item.json;
const validIds = prep.valid_ids || [];
let requirements;
try {
  const t = httpResp.candidates[0].content.parts[0].text;
  const parsed = (typeof t === 'string') ? JSON.parse(t) : t;
  requirements = parsed.requirements;
  if (!Array.isArray(requirements)) { throw new Error('response has no requirements array'); }
} catch (e) {
  return [{ json: { __error: true, message: 'LLM response failed schema validation: ' + e.message } }];
}
const validSet = new Set(validIds);
const cleaned = [];
for (let i = 0; i < requirements.length; i++) {
  const r = requirements[i];
  const src = (r.source_segment_ids || []).filter(function (id) {
    const ok = validSet.has(id);
    if (!ok) { console.warn('Dropping hallucinated segment id: ' + id); }
    return ok;
  });
  cleaned.push({
    req_id: 'req_' + String(i + 1).padStart(3, '0'),
    requirement_text: r.requirement_text,
    category: r.category,
    criticality: r.criticality,
    source_segment_ids: src,
  });
}
const auditState = JSON.parse(prep.audit_state);
auditState.requirements = cleaned;
return [{ json: { __error: false, session_id: prep.session_id, audit_state: JSON.stringify(auditState), requirements: cleaned } }];

const raw = $input.first().json;
const auditState = JSON.parse(raw.audit_state);
const requirements = auditState.requirements || [];
const draftSegs = auditState.draft_segments || [];
if (!requirements.length) {
  return [{ json: { has_inputs: false, reason: 'no_requirements', session_id: raw.session_id } }];
}
if (!draftSegs.length) {
  return [{ json: { has_inputs: false, reason: 'no_draft', session_id: raw.session_id } }];
}
let reqText = '';
for (let i = 0; i < requirements.length; i++) {
  const r = requirements[i];
  reqText += r.req_id + ' [' + r.category + ', ' + r.criticality + ']: ' + r.requirement_text + '\n';
}
let draftText = '';
for (let i = 0; i < draftSegs.length; i++) {
  draftText += '[' + draftSegs[i].id + '] "' + draftSegs[i].text + '"\n';
}
const reqIds = requirements.map(function (r) { return r.req_id; });
const reqMeta = requirements.map(function (r) { return { req_id: r.req_id, criticality: r.criticality }; });
const validDraftIds = draftSegs.map(function (s) { return s.id; });
const prompt = [
  'You are a senior proposal compliance analyst.',
  'For EVERY requirement below, decide whether the DRAFT PROPOSAL satisfies it, and cite the exact draft segment id(s) that prove your judgment.',
  'Rules:',
  '- status MUST be exactly one of: met, weak, missing.',
  '- Judge coverage on MEANING, not keyword overlap. If the draft is only directionally present and does not confirm the specific requirement, use "weak", not "met".',
  '- Never mark "met" on inference alone. If the draft is vague or defers detail (for example "pricing provided upon further discussion"), that is "missing", not "weak" - deferral is a gap.',
  '- matched_segment_ids MUST only reference draft segment ids that appear in the DRAFT PROPOSAL list below. Never invent an id.',
  '- rationale: 1 to 3 sentences; when status is not "missing" it MUST reference specific draft wording.',
  '- For any requirement whose criticality is "hard" and whose status is "missing", prefix rationale with "[CRITICAL GAP] ".',
  '- confidence is a float between 0.0 and 1.0.',
  '- Return exactly one object for EVERY requirement id listed. Do not skip any.',
  '',
  'REQUIREMENTS:',
  reqText,
  'DRAFT PROPOSAL SEGMENTS:',
  draftText,
].join('\n');
const responseSchema = {
  type: 'OBJECT',
  properties: {
    results: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          req_id: { type: 'STRING' },
          status: { type: 'STRING' },
          matched_segment_ids: { type: 'ARRAY', items: { type: 'STRING' } },
          rationale: { type: 'STRING' },
          confidence: { type: 'NUMBER' },
        },
        required: ['req_id', 'status', 'matched_segment_ids', 'rationale', 'confidence'],
      },
    },
  },
  required: ['results'],
};
const requestBody = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: 'application/json', responseSchema: responseSchema, temperature: 0.2 },
};
return [{ json: { has_inputs: true, session_id: raw.session_id, audit_state: raw.audit_state, req_ids: reqIds, req_meta: reqMeta, valid_draft_ids: validDraftIds, request_body: requestBody } }];

const httpResp = $input.first().json;
const prep = $('Prepare gap analysis').item.json;
const validDraftIds = prep.valid_draft_ids || [];
const reqIds = prep.req_ids || [];
const reqMeta = prep.req_meta || [];
const critById = {};
for (let i = 0; i < reqMeta.length; i++) { critById[reqMeta[i].req_id] = reqMeta[i].criticality; }
let results;
try {
  const t = httpResp.candidates[0].content.parts[0].text;
  const parsed = (typeof t === 'string') ? JSON.parse(t) : t;
  results = parsed.results;
  if (!Array.isArray(results)) { throw new Error('response has no results array'); }
} catch (e) {
  return [{ json: { __error: true, message: 'LLM response failed schema validation: ' + e.message } }];
}
const validDraftSet = new Set(validDraftIds);
const allowedStatus = new Set(['met', 'weak', 'missing']);
const byReq = {};
for (let i = 0; i < results.length; i++) {
  const r = results[i] || {};
  if (!r.req_id) { continue; }
  if (reqIds.indexOf(r.req_id) === -1) { continue; }
  if (byReq[r.req_id]) { continue; }
  let status = allowedStatus.has(r.status) ? r.status : 'missing';
  let conf = (typeof r.confidence === 'number') ? r.confidence : 0;
  const rawMatched = Array.isArray(r.matched_segment_ids) ? r.matched_segment_ids : [];
  const matched = rawMatched.filter(function (id) { return validDraftSet.has(id); });
  if (matched.length < rawMatched.length) { conf = Math.max(0, conf - 0.2); }
  let rationale = (typeof r.rationale === 'string') ? r.rationale : '';
  if ((status === 'met' || status === 'weak') && matched.length === 0) {
    status = 'missing';
    rationale = 'no supporting segment found';
  }
  if (critById[r.req_id] === 'hard' && status === 'missing' && rationale.indexOf('[CRITICAL GAP]') === -1) {
    rationale = '[CRITICAL GAP] ' + rationale;
  }
  conf = Math.min(1, Math.max(0, conf));
  byReq[r.req_id] = { req_id: r.req_id, status: status, matched_segment_ids: matched, rationale: rationale, confidence: conf };
}
const finalResults = [];
for (let i = 0; i < reqIds.length; i++) {
  const id = reqIds[i];
  if (byReq[id]) { finalResults.push(byReq[id]); continue; }
  let rationale = 'Agent did not evaluate this requirement - flagged for manual review';
  if (critById[id] === 'hard') { rationale = '[CRITICAL GAP] ' + rationale; }
  finalResults.push({ req_id: id, status: 'missing', matched_segment_ids: [], rationale: rationale, confidence: 0 });
}
const summary = { met: 0, weak: 0, missing: 0, total: finalResults.length };
for (let i = 0; i < finalResults.length; i++) { summary[finalResults[i].status] = (summary[finalResults[i].status] || 0) + 1; }
const auditState = JSON.parse(prep.audit_state);
const matrix = { session_id: prep.session_id, results: finalResults, coverage_summary: summary };
auditState.compliance_matrix = matrix;
return [{ json: { __error: false, session_id: prep.session_id, audit_state: JSON.stringify(auditState), compliance_matrix: matrix } }];

const raw = $input.first().json;
const body = ($('POST /audit/session/score').first().json.body) || {};
const auditState = JSON.parse(raw.audit_state);
const matrix = auditState.compliance_matrix;
const CRITERIA = ['PROBLEM_UNDERSTANDING','SCOPE_CLARITY','PRICING_TRANSPARENCY','TIMELINE_REALISM','COMPLETENESS','TONE_PROFESSIONALISM','RISK_TRANSPARENCY'];
const LLM_CRITERIA = ['PROBLEM_UNDERSTANDING','SCOPE_CLARITY','PRICING_TRANSPARENCY','TIMELINE_REALISM','TONE_PROFESSIONALISM'];
if (!matrix || !matrix.coverage_summary) {
  return [{ json: { ready: false, session_id: raw.session_id, error: 'compliance_matrix missing; run /analyze-gaps first (Sprint 2)' } }];
}
const defaultW = 1 / 7;
const weights = {};
const weightsProvided = !!(body && body.weights && typeof body.weights === 'object');
if (weightsProvided) {
  const keys = Object.keys(body.weights);
  let sum = 0;
  for (let i = 0; i < keys.length; i++) { const v = body.weights[keys[i]]; if (typeof v === 'number') sum += v; }
  if (Math.abs(sum - 1.0) > 0.01) {
    return [{ json: { ready: false, session_id: raw.session_id, error: 'weights must sum to 1.0 (tolerance 0.01); received sum=' + sum.toFixed(4) } }];
  }
  for (let i = 0; i < CRITERIA.length; i++) { const c = CRITERIA[i]; weights[c] = (typeof body.weights[c] === 'number') ? body.weights[c] : 0; }
} else {
  for (let i = 0; i < CRITERIA.length; i++) { weights[CRITERIA[i]] = defaultW; }
}
const cs = matrix.coverage_summary;
const total = cs.total || ((cs.met || 0) + (cs.weak || 0) + (cs.missing || 0));
let derivedScore = 1;
if (total) { derivedScore = Math.round(1 + 4 * ((cs.met || 0) + 0.5 * (cs.weak || 0)) / total); if (derivedScore < 1) derivedScore = 1; if (derivedScore > 5) derivedScore = 5; }
const derived = {
  COMPLETENESS: { criterion: 'COMPLETENESS', score_1to5: derivedScore, comment: 'Derived from requirement coverage: ' + (cs.met || 0) + ' met, ' + (cs.weak || 0) + ' weak, ' + (cs.missing || 0) + ' missing of ' + total + ' requirements.', weight: weights.COMPLETENESS },
  RISK_TRANSPARENCY: { criterion: 'RISK_TRANSPARENCY', score_1to5: derivedScore, comment: 'Derived from coverage; unmet/weak requirements are unaddressed risks (' + (cs.missing || 0) + ' missing, ' + (cs.weak || 0) + ' weak).', weight: weights.RISK_TRANSPARENCY },
};
const draftSegs = auditState.draft_segments || [];
let draftText = '';
for (let i = 0; i < draftSegs.length; i++) { draftText += '[' + draftSegs[i].id + '] ' + draftSegs[i].text + '\n'; }
if (!draftText) draftText = '(no draft text available)';
const prompt = [
  'You are a senior proposal evaluator. Score the DRAFT PROPOSAL on exactly these 5 criteria, each 1 (poor) to 5 (excellent):',
  '- PROBLEM_UNDERSTANDING: does the draft show clear grasp of the client problem?',
  '- SCOPE_CLARITY: is the proposed scope specific and well-bounded?',
  '- PRICING_TRANSPARENCY: is pricing clear, itemized and unambiguous? Deferred or vague pricing scores low.',
  '- TIMELINE_REALISM: is the proposed timeline concrete and realistic?',
  '- TONE_PROFESSIONALISM: is the writing professional, confident and well-structured?',
  'Rules:',
  '- score_1to5 is an integer 1..5.',
  '- comment: 1 to 2 sentences citing specific draft wording or a segment id where possible.',
  '- Return exactly one object per criterion using the exact criterion names above.',
  '',
  'DRAFT PROPOSAL SEGMENTS:',
  draftText,
].join('\n');
const responseSchema = { type: 'OBJECT', properties: { scores: { type: 'ARRAY', items: { type: 'OBJECT', properties: { criterion: { type: 'STRING' }, score_1to5: { type: 'INTEGER' }, comment: { type: 'STRING' } }, required: ['criterion','score_1to5','comment'] } } }, required: ['scores'] };
const requestBody = { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', responseSchema: responseSchema, temperature: 0.3 } };
return [{ json: { ready: true, session_id: raw.session_id, audit_state: raw.audit_state, weights: weights, derived: derived, llm_criteria: LLM_CRITERIA, criteria_order: CRITERIA, request_body: requestBody } }];

const httpResp = $input.first().json;
const prep = $('Prepare scoring').first().json;
const weights = prep.weights || {};
const derived = prep.derived || {};
const order = prep.criteria_order || [];
let scores;
try {
  const t = httpResp.candidates[0].content.parts[0].text;
  const parsed = (typeof t === 'string') ? JSON.parse(t) : t;
  scores = parsed.scores;
  if (!Array.isArray(scores)) { throw new Error('response has no scores array'); }
} catch (e) {
  return [{ json: { __error: true, message: 'LLM response failed schema validation: ' + e.message } }];
}
const byCrit = {};
for (let i = 0; i < scores.length; i++) { const s = scores[i] || {}; if (s.criterion) byCrit[s.criterion] = s; }
const criteria = [];
for (let i = 0; i < order.length; i++) {
  const c = order[i];
  if (derived[c]) { criteria.push(derived[c]); continue; }
  const s = byCrit[c] || {};
  let sc = parseInt(s.score_1to5, 10); if (isNaN(sc)) sc = 1; if (sc < 1) sc = 1; if (sc > 5) sc = 5;
  const comment = (typeof s.comment === 'string' && s.comment) ? s.comment : 'No comment returned by evaluator.';
  criteria.push({ criterion: c, score_1to5: sc, comment: comment, weight: (typeof weights[c] === 'number') ? weights[c] : 0 });
}
let overall = 0;
for (let i = 0; i < criteria.length; i++) { overall += (criteria[i].weight || 0) * criteria[i].score_1to5; }
overall = Math.round(overall * 10000) / 10000;
const scorecard = { session_id: prep.session_id, criteria: criteria, overall_score: overall };
const auditState = JSON.parse(prep.audit_state);
auditState.scorecard = scorecard;
return [{ json: { __error: false, session_id: prep.session_id, audit_state: JSON.stringify(auditState), scorecard: scorecard } }];

const raw = $input.first().json;
const body = ($('POST /audit/session/rescore').first().json.body) || {};
const auditState = JSON.parse(raw.audit_state);
const scorecard = auditState.scorecard;
if (!scorecard || !Array.isArray(scorecard.criteria) || !scorecard.criteria.length) {
  return [{ json: { ready: false, session_id: raw.session_id, error: 'scorecard missing; run /score first' } }];
}
if (!body || !body.weights || typeof body.weights !== 'object') {
  return [{ json: { ready: false, session_id: raw.session_id, error: 'weights are required in the request body' } }];
}
const keys = Object.keys(body.weights);
let sum = 0;
for (let i = 0; i < keys.length; i++) { const v = body.weights[keys[i]]; if (typeof v === 'number') sum += v; }
if (Math.abs(sum - 1.0) > 0.01) {
  return [{ json: { ready: false, session_id: raw.session_id, error: 'weights must sum to 1.0 (tolerance 0.01); received sum=' + sum.toFixed(4) } }];
}
const criteria = [];
let overall = 0;
for (let i = 0; i < scorecard.criteria.length; i++) {
  const c = scorecard.criteria[i];
  const w = (typeof body.weights[c.criterion] === 'number') ? body.weights[c.criterion] : 0;
  criteria.push({ criterion: c.criterion, score_1to5: c.score_1to5, comment: c.comment, weight: w });
  overall += w * c.score_1to5;
}
overall = Math.round(overall * 10000) / 10000;
const newCard = { session_id: raw.session_id, criteria: criteria, overall_score: overall };
auditState.scorecard = newCard;
return [{ json: { ready: true, session_id: raw.session_id, audit_state: JSON.stringify(auditState), scorecard: newCard } }];

const raw = $input.first().json;
const auditState = JSON.parse(raw.audit_state);
const matrix = auditState.compliance_matrix;
if (!matrix || !Array.isArray(matrix.results)) {
  return [{ json: { route: 'no_compliance', session_id: raw.session_id, error: 'compliance_matrix missing; run /analyze-gaps first (Sprint 2)' } }];
}
const requirements = auditState.requirements || [];
const reqById = {}; for (let i = 0; i < requirements.length; i++) { reqById[requirements[i].req_id] = requirements[i]; }
const draftSegs = auditState.draft_segments || [];
const segById = {}; for (let i = 0; i < draftSegs.length; i++) { segById[draftSegs[i].id] = draftSegs[i]; }
const validDraftIds = draftSegs.map(function (s) { return s.id; });
const lastSegId = validDraftIds.length ? validDraftIds[validDraftIds.length - 1] : null;
const targets = [];
for (let i = 0; i < matrix.results.length; i++) {
  const r = matrix.results[i];
  if (r.status !== 'weak' && r.status !== 'missing') continue;
  const req = reqById[r.req_id] || {};
  const matched = Array.isArray(r.matched_segment_ids) ? r.matched_segment_ids.filter(function (id) { return segById[id]; }) : [];
  targets.push({ req_id: r.req_id, status: r.status, criticality: req.criticality || 'unknown', requirement_text: req.requirement_text || '', category: req.category || '', matched_segment_ids: matched });
}
if (!targets.length) {
  auditState.rewrites = { session_id: raw.session_id, suggestions: [] };
  return [{ json: { route: 'empty', session_id: raw.session_id, audit_state: JSON.stringify(auditState), rewrites: auditState.rewrites } }];
}
let draftText = '';
for (let i = 0; i < draftSegs.length; i++) { draftText += '[' + draftSegs[i].id + '] ' + draftSegs[i].text + '\n'; }
if (!draftText) draftText = '(draft is empty)';
let reqBlock = '';
for (let i = 0; i < targets.length; i++) {
  const t = targets[i];
  let matchedText = '';
  for (let j = 0; j < t.matched_segment_ids.length; j++) { const seg = segById[t.matched_segment_ids[j]]; if (seg) { matchedText += '  matched [' + seg.id + ']: ' + seg.text + '\n'; } }
  if (!matchedText) matchedText = '  (no matching draft segment)\n';
  reqBlock += t.req_id + ' [status=' + t.status + ', criticality=' + t.criticality + ']: ' + t.requirement_text + '\n' + matchedText + '\n';
}
const prompt = [
  'You are a senior proposal writer. For each REQUIREMENT below, produce copy-pasteable proposal text that satisfies it.',
  'Rules:',
  '- suggested_text must be literal, ready-to-paste prose with no meta commentary.',
  '- The text MUST explicitly reference the specific RFP requirement it satisfies (quote the concrete detail, e.g. a stated budget range or named technology).',
  '- NEVER fabricate specific numbers, dates, prices, or names that do not appear in the requirement or draft. If a concrete figure is genuinely unknown, output a bracketed placeholder such as "[INSERT FINAL QUOTE - must fall within the RFP stated range]" instead of inventing a value. This is a hard rule.',
  '- If status is "weak" and a matched segment exists, write a full replacement paragraph for that segment.',
  '- If status is "missing", write a new paragraph and choose insertion_after_segment_id from the DRAFT SEGMENT ids listed (the id after which the new paragraph should be inserted).',
  '- rationale: 1 sentence explaining what the rewrite fixes.',
  '- Return exactly one object per requirement id.',
  '',
  'REQUIREMENTS NEEDING REWRITE:',
  reqBlock,
  'FULL DRAFT SEGMENTS (for placement):',
  draftText,
].join('\n');
